package tests

import (
	"errors"
	"sync"
	"testing"

	"exercise/src/catalog"
)

// memStore is an in-memory Store. OnSave runs just before a write is applied,
// standing in for a storefront request that lands while the update is in flight.
type memStore struct {
	mu      sync.Mutex
	rows    map[string]catalog.Product
	loads   int
	saves   int
	OnSave  func()
	SaveErr error
}

func newStore(products ...catalog.Product) *memStore {
	s := &memStore{rows: map[string]catalog.Product{}}
	for _, p := range products {
		s.rows[p.ID] = p
	}
	return s
}

func (s *memStore) Load(id string) (catalog.Product, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.loads++
	p, ok := s.rows[id]
	if !ok {
		return catalog.Product{}, catalog.ErrNotFound
	}
	return p, nil
}

func (s *memStore) Save(p catalog.Product) error {
	if s.OnSave != nil {
		s.OnSave()
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.SaveErr != nil {
		return s.SaveErr
	}
	s.saves++
	s.rows[p.ID] = p
	return nil
}

func setup() (*memStore, *catalog.Catalog) {
	store := newStore(
		catalog.Product{ID: "p1", Name: "Espresso machine", PriceCents: 12000},
		catalog.Product{ID: "p2", Name: "Grinder", PriceCents: 4500},
	)
	return store, catalog.New(store, catalog.NewCache())
}

func TestGetReadsThroughAndCaches(t *testing.T) {
	store, cat := setup()
	for i := 0; i < 3; i++ {
		p, err := cat.Get("p1")
		if err != nil || p.PriceCents != 12000 {
			t.Fatalf("Get = %+v, %v", p, err)
		}
	}
	if store.loads != 1 {
		t.Fatalf("store read %d times for 3 Gets, want 1", store.loads)
	}
}

func TestUpdatePriceIsVisibleAfterwards(t *testing.T) {
	_, cat := setup()
	cat.Get("p1")
	if err := cat.UpdatePrice("p1", 9900); err != nil {
		t.Fatal(err)
	}
	p, _ := cat.Get("p1")
	if p.PriceCents != 9900 {
		t.Fatalf("price after update = %d, want 9900", p.PriceCents)
	}
}

func TestReaderDuringUpdateDoesNotPinOldPrice(t *testing.T) {
	store, cat := setup()
	cat.Get("p1")
	store.OnSave = func() { cat.Get("p1") }
	if err := cat.UpdatePrice("p1", 9900); err != nil {
		t.Fatal(err)
	}
	p, _ := cat.Get("p1")
	t.Logf("store price: %d, price served after the update: %d", store.rows["p1"].PriceCents, p.PriceCents)
	if p.PriceCents != 9900 {
		t.Fatalf("storefront still serves %d after the update committed 9900", p.PriceCents)
	}
}

func TestCartUsesNewPriceAfterBusyUpdate(t *testing.T) {
	store, cat := setup()
	store.OnSave = func() { cat.Get("p1") }
	if err := cat.UpdatePrice("p1", 10000); err != nil {
		t.Fatal(err)
	}
	total, err := catalog.CartTotal(cat, []catalog.Item{{ProductID: "p1", Qty: 2}, {ProductID: "p2", Qty: 1}})
	if err != nil {
		t.Fatal(err)
	}
	if total != 24500 {
		t.Fatalf("cart total = %d, want 24500 (2 x 10000 + 4500)", total)
	}
}

func TestUpdateUnknownProduct(t *testing.T) {
	store, cat := setup()
	err := cat.UpdatePrice("nope", 100)
	if !errors.Is(err, catalog.ErrNotFound) {
		t.Fatalf("err = %v, want ErrNotFound", err)
	}
	if store.saves != 0 {
		t.Fatal("nothing should be saved for an unknown product")
	}
}

func TestInvalidPriceKeepsCachedValue(t *testing.T) {
	store, cat := setup()
	cat.Get("p1")
	if err := cat.UpdatePrice("p1", 0); !errors.Is(err, catalog.ErrInvalidPrice) {
		t.Fatalf("err = %v, want ErrInvalidPrice", err)
	}
	cat.Get("p1")
	if store.loads != 1 {
		t.Fatalf("a rejected update should not evict the cache, but the store was read %d times", store.loads)
	}
}

func TestFailedSaveKeepsOldPrice(t *testing.T) {
	store, cat := setup()
	store.SaveErr = errors.New("connection reset")
	if err := cat.UpdatePrice("p1", 9900); err == nil {
		t.Fatal("expected the save error to be returned")
	}
	p, _ := cat.Get("p1")
	if p.PriceCents != 12000 {
		t.Fatalf("price = %d after a failed update, want the old 12000", p.PriceCents)
	}
}
